.menu { position: relative; display: inline-block; }
.menu-items { display: none; position: absolute; margin: 4px 0 0; padding: 4px 8px; list-style: none; border: 1px solid #888; background: #fff; }
.menu:hover .menu-items, .menu:focus-within .menu-items { display: block; }
.switch { position: relative; display: inline-block; }
.switch input { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; opacity: 0; }
.switch label { position: relative; display: inline-block; padding: 4px 8px; border: 1px solid #888; }

const probeLog = document.getElementById('probe-log');
const record = (text) => { probeLog.textContent = text; };
document.getElementById('probe').addEventListener('click', () => record('click'));
document.getElementById('probe').addEventListener('dblclick', () => record('dblclick'));
document.getElementById('probe').addEventListener('contextmenu', () => record('contextmenu'));
document.getElementById('far-button').addEventListener('click', () => record('far-click'));

// A framework-style controlled field: the value lives in JS, it is accepted from an `input`
// event, and anything that changed the field without saying so is written back over.
const controlled = document.getElementById('controlled');
let controlledState = '';
controlled.addEventListener('input', () => { controlledState = controlled.value; });
setInterval(() => {
  if (controlled.value !== controlledState) controlled.value = controlledState;
}, 25);

// A request the page starts itself, so a settle has something real to wait for.
document.getElementById('slow-fetch').addEventListener('click', async () => {
  document.getElementById('slow-done').textContent = 'loading';
  // The body is read, so the request actually finishes; a response nobody consumes stays
  // open as far as the network domain is concerned.
  await (await fetch('/slow?ms=1500')).json();
  document.getElementById('slow-done').textContent = 'yes';
});

